front.load():
  request = { path: '/uifa-board-v1' }
  return back.get(request)

back.get(request):
  request.url = config.apiBase + request.path
  request.limit = config.timeoutMs
  send(request)

wait(request):
  race api.answer(request) against timer(request.limit)
  if the timer wins: abandon(request); raise Timeout
  if the connection drops: abandon(request); raise ConnectionLost

back.translate(reply):
  if reply is Timeout: return failure('timeout')
  if reply is ConnectionLost: return failure('network')
  if reply.status is not 2xx: return failure('http', reply.status)
  return board(reply.body)    // the body's version is not checked

store.load():
  outcome = front.load()
  if outcome is a board: dispatch loadSuccess(outcome)
  else: dispatch loadFailure(outcome)

