// Illustrative: the app loads study chunks with promises and none of this runs; defer shows the import waiting for its first reader, and shareReplay shows later readers sharing it.
const poeaaStudies$ = defer(() => import('../studies/poeaa')).pipe(
  map(({ default: records }) => records),
  shareReplay(1),
);

const study$ = (id: ToolId) =>
  poeaaStudies$.pipe(map((records) => records.find((study) => study.id === id) ?? null));

// The first subscription starts the import and later ones replay its records. shareReplay
// resets after an error, so a reading that failed subscribes again and the import is retried.
study$('poeaa:260').subscribe(showStudy);

// Illustrative: a registry entry kept as a deferred stream shared through a replaying subject
// (shareReplay(1)), so the first lookup in a scope builds the loader and every later lookup there
// receives the same one. Nothing in this study runs RxJS; the tested model is plain TypeScript.
const scopes = new Map<string, Map<string, Observable<CatalogLoader>>>();

function provide(scope: string, key: string, factory: () => CatalogLoader): void {
  const entries = scopes.get(scope) ?? new Map<string, Observable<CatalogLoader>>();
  entries.set(key, defer(() => of(factory())).pipe(shareReplay(1)));
  scopes.set(scope, entries);
}

function lookup(scope: string, key: string): Observable<CatalogLoader> {
  return (
    scopes.get(scope)?.get(key) ??
    throwError(() => new Error('nothing is registered under this key'))
  );
}

function closePage(scope: string): void {
  scopes.delete(scope);
}

provide('tools', 'catalog', createCatalogLoader);
provide('scene', 'catalog', createCatalogLoader);
lookup('tools', 'catalog').subscribe(readHome); // builds loader 1
lookup('tools', 'catalog').subscribe(readCatalogPage); // replays loader 1
lookup('scene', 'catalog').subscribe(readScene); // builds loader 2

// Illustrative: the facade's local reads as an RxJS reader would write them, to show where a failed part is caught; nothing in this batch runs it, and the reads here run together where the drawing steps them one at a time.
const loadBoard = (caller: Caller) =>
  requireReader(caller).pipe(
    switchMap(() => sources.panelIds()),
    switchMap((ids) =>
      forkJoin(
        ids.map((id) =>
          sources.panel(id).pipe(
            // A failed part stays a part: without this, one failed read errors the forkJoin, and the call.
            catchError((failure) => of(unavailablePanel(id, failure.reason))),
          ),
        ),
      ),
    ),
    map((panels) => ({ viewModelVersion: 'uifa-board-v1', panels })),
  );

