domain.check(composition, stored, sceneId):
  if composition.sceneId != sceneId: return refused('another scene')
  id = highest id in stored + 1
  return accepted(composition with id)

saveComposition(tab, composition):
  stored = storage.read()
  verdict = domain.check(composition, stored, tab.sceneId)
  if verdict is refused: return verdict

  list = stored + [verdict.composition]
  if not storage.setItem(list): return failed

  tab.listeners.announce(verdict.composition)
  return saved(verdict.composition)
